/// <summary>
/// PaffH 05.01.22
/// </summary>
/// <param name = "_prodId">ProdId</param>
/// <returns>ProdId</returns>
[DataMember('ProdId'), BusinessEventsDataMember("Production Id")]
public ProdId ParmProdId(ProdId _prodId = ProdId)
{
    prodId = _prodId;
    return prodId;
}
